const { World, setWorldConstructor } = require('@cucumber/cucumber');
const { Window } = require('happy-dom');
const fs = require('fs');
const path = require('path');

class AppWorld extends World {
  constructor(options) {
    super(options);
    this.window = null;
    this.document = null;
  }

  loadApp() {
    const htmlPath = path.resolve(__dirname, '..', '..', 'index.html');
    const html = fs.readFileSync(htmlPath, 'utf-8');
    this.window = new Window({ url: 'http://localhost/' });
    this.document = this.window.document;
    this.document.write(html);
    this.document.close();
  }

  getTodoItems() {
    return Array.from(this.document.querySelectorAll('.todo-list li'));
  }

  getNewTodoInput() {
    return this.document.querySelector('.new-todo');
  }

  getToggleAllCheckbox() {
    return this.document.querySelector('#toggle-all');
  }

  getMainSection() {
    return this.document.querySelector('.main');
  }

  getFooter() {
    return this.document.querySelector('.footer');
  }

  getCounter() {
    return this.document.querySelector('.todo-count');
  }

  getClearCompletedButton() {
    return this.document.querySelector('.clear-completed');
  }

  getFilterLinks() {
    return Array.from(this.document.querySelectorAll('.filters a'));
  }
}

setWorldConstructor(AppWorld);

const { Given, When, Then } = require('@cucumber/cucumber');
const { expect } = require('chai');
const fs = require('fs');
const path = require('path');

// ==================== App Loading ====================

Given('a file {string} exists at the project root', function (filename) {
  const filePath = path.resolve(__dirname, '..', '..', filename);
  expect(fs.existsSync(filePath)).to.be.true;
});

Then('the file contains an input element with class {string}', function (className) {
  const filePath = path.resolve(__dirname, '..', '..', 'index.html');
  const html = fs.readFileSync(filePath, 'utf-8');
  expect(html).to.include(`class="${className}"`);
});

Then('the file contains a section element with class {string}', function (className) {
  const filePath = path.resolve(__dirname, '..', '..', 'index.html');
  const html = fs.readFileSync(filePath, 'utf-8');
  expect(html).to.include(`class="${className}"`);
});

Then('the file contains a footer element with class {string}', function (className) {
  const filePath = path.resolve(__dirname, '..', '..', 'index.html');
  const html = fs.readFileSync(filePath, 'utf-8');
  expect(html).to.include(`class="${className}"`);
});

Then('the file contains a script tag loading {string}', function (src) {
  const filePath = path.resolve(__dirname, '..', '..', 'index.html');
  const html = fs.readFileSync(filePath, 'utf-8');
  expect(html).to.include(`src="${src}"`);
});

// ==================== App Setup ====================

Given('the todo app is loaded', function () {
  this.loadApp();
});

// ==================== Creating Todos ====================

When('the user types {string} in the new todo input', function (text) {
  const input = this.getNewTodoInput();
  input.value = text;
  input.dispatchEvent(new this.window.Event('input', { bubbles: true }));
});

When('the user presses Enter', function () {
  const input = this.getNewTodoInput();
  input.dispatchEvent(new this.window.KeyboardEvent('keydown', { key: 'Enter', keyCode: 13, bubbles: true }));
});

When('the user presses Escape', function () {
  const editingInput = this.document.querySelector('.todo-list li.editing .edit');
  if (editingInput) {
    editingInput.dispatchEvent(new this.window.KeyboardEvent('keydown', { key: 'Escape', keyCode: 27, bubbles: true }));
  }
});

Then('the todo list contains {int} item(s)', function (count) {
  const items = this.getTodoItems();
  expect(items.length).to.equal(count);
});

Then('the first todo has title {string}', function (title) {
  const items = this.getTodoItems();
  expect(items.length).to.be.greaterThan(0);
  const label = items[0].querySelector('label');
  expect(label.textContent).to.equal(title);
});

Then('the second todo has title {string}', function (title) {
  const items = this.getTodoItems();
  expect(items.length).to.be.greaterThan(1);
  const label = items[1].querySelector('label');
  expect(label.textContent).to.equal(title);
});

Then('the first todo is not completed', function () {
  const items = this.getTodoItems();
  expect(items.length).to.be.greaterThan(0);
  const checkbox = items[0].querySelector('.toggle');
  expect(checkbox.checked).to.be.false;
});

Then('the new todo input is empty', function () {
  const input = this.getNewTodoInput();
  expect(input.value).to.equal('');
});

// ==================== Toggling Todos ====================

Given('a todo {string} exists', function (title) {
  const input = this.getNewTodoInput();
  input.value = title;
  input.dispatchEvent(new this.window.Event('input', { bubbles: true }));
  input.dispatchEvent(new this.window.KeyboardEvent('keydown', { key: 'Enter', keyCode: 13, bubbles: true }));
});

Given('a completed todo {string} exists', function (title) {
  const input = this.getNewTodoInput();
  input.value = title;
  input.dispatchEvent(new this.window.Event('input', { bubbles: true }));
  input.dispatchEvent(new this.window.KeyboardEvent('keydown', { key: 'Enter', keyCode: 13, bubbles: true }));
  const items = this.getTodoItems();
  const checkbox = items[items.length - 1].querySelector('.toggle');
  checkbox.click();
});

When('the user clicks the toggle checkbox of the first todo', function () {
  const items = this.getTodoItems();
  expect(items.length).to.be.greaterThan(0);
  const checkbox = items[0].querySelector('.toggle');
  checkbox.click();
});

When('the user clicks the toggle checkbox of the second todo', function () {
  const items = this.getTodoItems();
  expect(items.length).to.be.greaterThan(1);
  const checkbox = items[1].querySelector('.toggle');
  checkbox.click();
});

Then('the first todo is completed', function () {
  const items = this.getTodoItems();
  expect(items.length).to.be.greaterThan(0);
  const checkbox = items[0].querySelector('.toggle');
  expect(checkbox.checked).to.be.true;
});

Then('the first todo element has class {string}', function (className) {
  const items = this.getTodoItems();
  expect(items.length).to.be.greaterThan(0);
  expect(items[0].classList.contains(className)).to.be.true;
});

Then('the first todo element does not have class {string}', function (className) {
  const items = this.getTodoItems();
  expect(items.length).to.be.greaterThan(0);
  expect(items[0].classList.contains(className)).to.be.false;
});

// ==================== Mark All Complete ====================

When('the user clicks the toggle-all checkbox', function () {
  const checkbox = this.getToggleAllCheckbox();
  checkbox.click();
});

Then('all todos are completed', function () {
  const items = this.getTodoItems();
  expect(items.length).to.be.greaterThan(0);
  items.forEach(item => {
    const checkbox = item.querySelector('.toggle');
    expect(checkbox.checked).to.be.true;
  });
});

Then('all todos are not completed', function () {
  const items = this.getTodoItems();
  expect(items.length).to.be.greaterThan(0);
  items.forEach(item => {
    const checkbox = item.querySelector('.toggle');
    expect(checkbox.checked).to.be.false;
  });
});

Then('the toggle-all checkbox is checked', function () {
  const checkbox = this.getToggleAllCheckbox();
  expect(checkbox.checked).to.be.true;
});

Then('the toggle-all checkbox is not checked', function () {
  const checkbox = this.getToggleAllCheckbox();
  expect(checkbox.checked).to.be.false;
});

// ==================== Editing Todos ====================

When('the user double-clicks the label of the first todo', function () {
  const items = this.getTodoItems();
  expect(items.length).to.be.greaterThan(0);
  const label = items[0].querySelector('label');
  label.dispatchEvent(new this.window.Event('dblclick', { bubbles: true }));
});

Then('the edit input of the first todo has value {string}', function (value) {
  const items = this.getTodoItems();
  expect(items.length).to.be.greaterThan(0);
  const editInput = items[0].querySelector('.edit');
  expect(editInput.value).to.equal(value);
});

Then('the edit input of the first todo is focused', function () {
  const items = this.getTodoItems();
  expect(items.length).to.be.greaterThan(0);
  const editInput = items[0].querySelector('.edit');
  expect(editInput).to.equal(this.document.activeElement);
});

When('the user types {string} in the edit input of the first todo', function (text) {
  const items = this.getTodoItems();
  expect(items.length).to.be.greaterThan(0);
  const editInput = items[0].querySelector('.edit');
  editInput.value = text;
  editInput.dispatchEvent(new this.window.Event('input', { bubbles: true }));
});

When('the user clears the edit input of the first todo', function () {
  const items = this.getTodoItems();
  expect(items.length).to.be.greaterThan(0);
  const editInput = items[0].querySelector('.edit');
  editInput.value = '';
  editInput.dispatchEvent(new this.window.Event('input', { bubbles: true }));
});

When('the edit input of the first todo loses focus', function () {
  const items = this.getTodoItems();
  expect(items.length).to.be.greaterThan(0);
  const editInput = items[0].querySelector('.edit');
  editInput.dispatchEvent(new this.window.Event('blur', { bubbles: true }));
});

// ==================== Deleting Todos ====================

When('the user clicks the destroy button of the first todo', function () {
  const items = this.getTodoItems();
  expect(items.length).to.be.greaterThan(0);
  const destroyBtn = items[0].querySelector('.destroy');
  destroyBtn.click();
});

// ==================== Clear Completed ====================

When('the user clicks the {string} button', function (buttonText) {
  const buttons = Array.from(this.document.querySelectorAll('button'));
  const button = buttons.find(b => b.textContent.trim() === buttonText);
  expect(button).to.exist;
  button.click();
});

Then('the {string} button is hidden', function (buttonText) {
  const buttons = Array.from(this.document.querySelectorAll('button'));
  const button = buttons.find(b => b.textContent.trim() === buttonText);
  expect(button).to.exist;
  expect(button.style.display === 'none' || button.classList.contains('hidden') || !button.offsetParent).to.be.true;
});

Then('the {string} button is visible', function (buttonText) {
  const buttons = Array.from(this.document.querySelectorAll('button'));
  const button = buttons.find(b => b.textContent.trim() === buttonText);
  expect(button).to.exist;
  expect(button.offsetParent).to.not.be.null;
});

// ==================== Counter ====================

Then('the counter shows {string}', function (text) {
  const counter = this.getCounter();
  expect(counter.textContent.trim()).to.equal(text);
});

// ==================== Filtering ====================

When('the user clicks the {string} filter', function (filterName) {
  const links = this.getFilterLinks();
  const link = links.find(a => a.textContent.trim() === filterName);
  expect(link).to.exist;
  link.click();
});

Then('the {string} filter is selected', function (filterName) {
  const links = this.getFilterLinks();
  const link = links.find(a => a.textContent.trim() === filterName);
  expect(link).to.exist;
  expect(link.classList.contains('selected')).to.be.true;
});

When('the user navigates to {string}', function (hash) {
  this.window.location.hash = hash;
  this.window.dispatchEvent(new this.window.Event('hashchange'));
});

// ==================== Persistence ====================

When('the page is reloaded', function () {
  const todos = JSON.parse(this.window.localStorage.getItem('todos-todomvc') || '[]');
  this.loadApp();
  this.window.localStorage.setItem('todos-todomvc', JSON.stringify(todos));
  // Re-trigger app initialization by dispatching DOMContentLoaded
  this.document.dispatchEvent(new this.window.Event('DOMContentLoaded'));
});

Then('localStorage contains key {string}', function (key) {
  const value = this.window.localStorage.getItem(key);
  expect(value).to.not.be.null;
});

// ==================== Visibility ====================

Then('the main section is hidden', function () {
  const main = this.getMainSection();
  expect(main.style.display === 'none' || main.classList.contains('hidden') || !main.offsetParent).to.be.true;
});

Then('the main section is visible', function () {
  const main = this.getMainSection();
  expect(main.offsetParent).to.not.be.null;
});

Then('the footer is hidden', function () {
  const footer = this.getFooter();
  expect(footer.style.display === 'none' || footer.classList.contains('hidden') || !footer.offsetParent).to.be.true;
});

Then('the footer is visible', function () {
  const footer = this.getFooter();
  expect(footer.offsetParent).to.not.be.null;
});

/* Base styles for TodoMVC */
* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

body {
  font: 14px 'Helvetica Neue', Helvetica, Arial, sans-serif;
  line-height: 1.4em;
  background: #f5f5f5;
  color: #4d4d4d;
  min-width: 230px;
  max-width: 550px;
  margin: 0 auto;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  font-weight: 300;
}

.todoapp {
  background: #fff;
  margin: 130px 0 40px 0;
  position: relative;
  box-shadow: 0 2px 4px 0 rgba(0, 0, 0, 0.2),
              0 25px 50px 0 rgba(0, 0, 0, 0.1);
}

.todoapp h1 {
  position: absolute;
  top: -155px;
  width: 100%;
  font-size: 100px;
  font-weight: 100;
  text-align: center;
  color: rgba(175, 47, 47, 0.15);
}

.todoapp input::-webkit-input-placeholder {
  font-style: italic;
  font-weight: 300;
  color: #e6e6e6;
}

.new-todo {
  position: relative;
  margin: 0;
  width: 100%;
  font-size: 24px;
  font-family: inherit;
  font-weight: inherit;
  line-height: 1.4em;
  border: 0;
  color: inherit;
  padding: 16px 16px 16px 60px;
  box-sizing: border-box;
  box-shadow: inset 0 -2px 1px rgba(0, 0, 0, 0.03);
}

.main {
  position: relative;
  z-index: 2;
  border-top: 1px solid #e6e6e6;
}

.toggle-all {
  width: 1px;
  height: 1px;
  border: none;
  opacity: 0;
  position: absolute;
  right: 100%;
  bottom: 100%;
}

.toggle-all + label {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 45px;
  height: 65px;
  font-size: 0;
  position: absolute;
  top: -65px;
  left: -15px;
  -webkit-transform: rotate(90deg);
  transform: rotate(90deg);
}

.toggle-all + label:before {
  content: '❯';
  display: inline-block;
  font-size: 22px;
  color: #949494;
  padding: 10px 27px 10px 27px;
}

.toggle-all:checked + label:before {
  color: #484848;
}

.todo-list {
  margin: 0;
  padding: 0;
  list-style: none;
}

.todo-list li {
  position: relative;
  font-size: 24px;
  border-bottom: 1px solid #ededed;
}

.todo-list li:last-child {
  margin-bottom: -1px;
}

.todo-list li .view {
  display: flex;
  align-items: center;
}

.todo-list li .toggle {
  text-align: center;
  width: 40px;
  height: auto;
  position: absolute;
  top: 0;
  bottom: 0;
  margin: auto 0;
  border: none;
  -webkit-appearance: none;
  appearance: none;
  cursor: pointer;
}

.todo-list li .toggle:after {
  content: url('data:image/svg+xml;utf8,%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20width%3D%2240%22%20height%3D%2240%22%20viewBox%3D%22-10%20-18%20100%20135%22%3E%3Ccircle%20cx%3D%2250%22%20cy%3D%2250%22%20r%3D%2250%22%20fill%3D%22none%22%20stroke%3D%22%23949494%22%20stroke-width%3D%223%22%2F%3E%3C%2Fsvg%3E');
  background-repeat: no-repeat;
  background-position: center left;
}

.todo-list li .toggle:checked:after {
  content: url('data:image/svg+xml;utf8,%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20width%3D%2240%22%20height%3D%2240%22%20viewBox%3D%22-10%20-18%20100%20135%22%3E%3Ccircle%20cx%3D%2250%22%20cy%3D%2250%22%20r%3D%2250%22%20fill%3D%22none%22%20stroke%3D%22%23bddad5%22%20stroke-width%3D%223%22%2F%3E%3Cpath%20fill%3D%22%235dc2af%22%20d%3D%22M72%2025L42%2071%2027%2056l-4%204%2020%2020%2034-52z%22%2F%3E%3C%2Fsvg%3E');
}

.todo-list li label {
  word-break: break-all;
  padding: 15px 15px 15px 60px;
  display: block;
  line-height: 1.2;
  transition: color 0.4s;
  font-weight: 400;
  color: #484848;
}

.todo-list li.completed label {
  color: #949494;
  text-decoration: line-through;
}

.todo-list li .destroy {
  display: none;
  position: absolute;
  top: 0;
  right: 10px;
  bottom: 0;
  width: 40px;
  height: 40px;
  margin: auto 0;
  font-size: 30px;
  color: #949494;
  transition: color 0.2s ease-out;
  cursor: pointer;
  background: none;
  border: none;
}

.todo-list li .destroy:after {
  content: '×';
}

.todo-list li:hover .destroy {
  display: block;
}

.todo-list li .edit {
  display: none;
}

.todo-list li.editing:last-child {
  margin-bottom: -1px;
}

.todo-list li.editing .edit {
  display: block;
  width: calc(100% - 43px);
  padding: 12px 16px;
  margin: 0 0 0 43px;
  font-size: inherit;
  font-family: inherit;
  font-weight: inherit;
  line-height: 1.4em;
  border: 0;
  color: inherit;
  box-shadow: inset 0 -1px 2px rgba(0, 0, 0, 0.03);
}

.todo-list li.editing .view {
  display: none;
}

.footer {
  color: #777;
  padding: 10px 15px;
  height: 20px;
  text-align: center;
  border-top: 1px solid #e6e6e6;
}

.footer:before {
  content: '';
  position: absolute;
  right: 0;
  bottom: 0;
  left: 0;
  height: 50px;
  overflow: hidden;
  box-shadow: 0 1px 1px rgba(0, 0, 0, 0.2),
              0 8px 0 -3px #f6f6f6,
