(function () {
  'use strict';

  var STORAGE_KEY = 'todos-todomvc';
  var ENTER_KEY = 13;
  var ESCAPE_KEY = 27;

  var todoList = document.querySelector('.todo-list');
  var newTodoInput = document.querySelector('.new-todo');
  var toggleAllCheckbox = document.querySelector('#toggle-all');
  var mainSection = document.querySelector('.main');
  var footer = document.querySelector('.footer');
  var todoCount = document.querySelector('.todo-count');
  var clearCompletedBtn = document.querySelector('.clear-completed');
  var filterLinks = document.querySelectorAll('.filters a');

  var todos = [];
  var currentFilter = 'all';

  function loadTodos() {
    try {
      var stored = localStorage.getItem(STORAGE_KEY);
      todos = stored ? JSON.parse(stored) : [];
    } catch (e) {
      todos = [];
    }
  }

  function saveTodos() {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(todos));
  }

  function generateId() {
    return Date.now().toString(36) + Math.random().toString(36).substr(2);
  }

  function addTodo(title) {
    var trimmed = title.trim();
    if (!trimmed) return;
    todos.push({
      id: generateId(),
      title: trimmed,
      completed: false
    });
    saveTodos();
    render();
  }

  function toggleTodo(id) {
    for (var i = 0; i < todos.length; i++) {
      if (todos[i].id === id) {
        todos[i].completed = !todos[i].completed;
        break;
      }
    }
    saveTodos();
    render();
  }

  function toggleAll() {
    var allCompleted = todos.every(function (t) { return t.completed; });
    todos.forEach(function (t) {
      t.completed = !allCompleted;
    });
    saveTodos();
    render();
  }

  function destroyTodo(id) {
    todos = todos.filter(function (t) { return t.id !== id; });
    saveTodos();
    render();
  }

  function editTodo(id, newTitle) {
    var trimmed = newTitle.trim();
    if (!trimmed) {
      destroyTodo(id);
      return;
    }
    for (var i = 0; i < todos.length; i++) {
      if (todos[i].id === id) {
        todos[i].title = trimmed;
        break;
      }
    }
    saveTodos();
    render();
  }

  function clearCompleted() {
    todos = todos.filter(function (t) { return !t.completed; });
    saveTodos();
    render();
  }

  function getFilteredTodos() {
    if (currentFilter === 'active') {
      return todos.filter(function (t) { return !t.completed; });
    } else if (currentFilter === 'completed') {
      return todos.filter(function (t) { return t.completed; });
    }
    return todos;
  }

  function updateCounter() {
    var active = todos.filter(function (t) { return !t.completed; }).length;
    var text = active === 1 ? '1 item left' : active + ' items left';
    todoCount.innerHTML = '<strong>' + active + '</strong> ' + (active === 1 ? 'item' : 'items') + ' left';
  }

  function updateVisibility() {
    if (todos.length === 0) {
      mainSection.style.display = 'none';
      footer.style.display = 'none';
    } else {
      mainSection.style.display = '';
      footer.style.display = '';
    }
  }

  function updateToggleAll() {
    var allCompleted = todos.length > 0 && todos.every(function (t) { return t.completed; });
    toggleAllCheckbox.checked = allCompleted;
  }

  function updateClearCompleted() {
    var hasCompleted = todos.some(function (t) { return t.completed; });
    if (hasCompleted) {
      clearCompletedBtn.classList.remove('hidden');
    } else {
      clearCompletedBtn.classList.add('hidden');
    }
  }

  function updateFilterLinks() {
    filterLinks.forEach(function (link) {
      link.classList.remove('selected');
      if (link.getAttribute('href') === '#/' + (currentFilter === 'all' ? '' : currentFilter)) {
        link.classList.add('selected');
      }
    });
  }

  function renderTodoItem(todo) {
    var li = document.createElement('li');
    li.setAttribute('data-id', todo.id);
    if (todo.completed) {
      li.classList.add('completed');
    }

    var viewDiv = document.createElement('div');
    viewDiv.className = 'view';

    var checkbox = document.createElement('input');
    checkbox.className = 'toggle';
    checkbox.type = 'checkbox';
    checkbox.checked = todo.completed;
    checkbox.addEventListener('click', function () {
      toggleTodo(todo.id);
    });

    var label = document.createElement('label');
    label.textContent = todo.title;
    label.addEventListener('dblclick', function () {
      li.classList.add('editing');
      var editInput = li.querySelector('.edit');
      editInput.focus();
    });

    var destroyBtn = document.createElement('button');
    destroyBtn.className = 'destroy';
    destroyBtn.addEventListener('click', function () {
      destroyTodo(todo.id);
    });

    viewDiv.appendChild(checkbox);
    viewDiv.appendChild(label);
    viewDiv.appendChild(destroyBtn);

    var editInput = document.createElement('input');
    editInput.className = 'edit';
    editInput.value = todo.title;
    editInput.addEventListener('blur', function () {
      editTodo(todo.id, editInput.value);
    });
    editInput.addEventListener('keydown', function (e) {
      if (e.keyCode === ENTER_KEY) {
        editInput.blur();
      } else if (e.keyCode === ESCAPE_KEY) {
        editInput.value = todo.title;
        editInput.blur();
        li.classList.remove('editing');
      }
    });

    li.appendChild(viewDiv);
    li.appendChild(editInput);

    return li;
  }

  function render() {
    todoList.innerHTML = '';
    var filtered = getFilteredTodos();
    filtered.forEach(function (todo) {
      todoList.appendChild(renderTodoItem(todo));
    });
    updateCounter();
    updateVisibility();
    updateToggleAll();
    updateClearCompleted();
    updateFilterLinks();
  }

  function handleHashChange() {
    var hash = window.location.hash || '#/';
    if (hash === '#/active') {
      currentFilter = 'active';
    } else if (hash === '#/completed') {
      currentFilter = 'completed';
    } else {
      currentFilter = 'all';
    }
    render();
  }

  function init() {
    loadTodos();
    handleHashChange();

    newTodoInput.addEventListener('keydown', function (e) {
      if (e.keyCode === ENTER_KEY) {
        addTodo(newTodoInput.value);
        newTodoInput.value = '';
      }
    });

    toggleAllCheckbox.addEventListener('click', function () {
      toggleAll();
    });

    clearCompletedBtn.addEventListener('click', function () {
      clearCompleted();
    });

    filterLinks.forEach(function (link) {
      link.addEventListener('click', function (e) {
        e.preventDefault();
        var href = link.getAttribute('href');
        window.location.hash = href;
      });
    });

    window.addEventListener('hashchange', handleHashChange);
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', init);
  } else {
    init();
  }
})();

