const { World, setWorldConstructor } = require('@cucumber/cucumber');
const { Window } = require('happy-dom');
const fs = require('fs');
const path = require('path');

class AppWorld extends World {
  constructor(options) {
    super(options);
    this.window = null;
    this.document = null;
  }

  loadApp() {
    const htmlPath = path.resolve(__dirname, '..', '..', 'index.html');
    const html = fs.readFileSync(htmlPath, 'utf-8');
    this.window = new Window({ url: 'http://localhost/' });
    this.document = this.window.document;
    this.document.write(html);
    this.document.close();

    // Inject globals that the app expects
    this.window.localStorage = this.window.localStorage;
    this.window.document = this.document;

    // Run the app script using the window's eval mechanism
    const appPath = path.resolve(__dirname, '..', '..', 'js', 'app.js');
    const appCode = fs.readFileSync(appPath, 'utf-8');

    // Create a function that has access to window globals
    const wrappedCode = `
      (function() {
        var document = window.document;
        var localStorage = window.localStorage;
        var window = window;
        ${appCode}
      })();
    `;

    // Use the window's script execution
    const scriptEl = this.document.createElement('script');
    scriptEl.textContent = appCode;
    this.document.body.appendChild(scriptEl);
  }

  getTodoItems() {
    return Array.from(this.document.querySelectorAll('.todo-list li'));
  }

  getNewTodoInput() {
    return this.document.querySelector('.new-todo');
  }

  getToggleAllCheckbox() {
    return this.document.querySelector('#toggle-all');
  }

  getMainSection() {
    return this.document.querySelector('.main');
  }

  getFooter() {
    return this.document.querySelector('.footer');
  }

  getCounter() {
    return this.document.querySelector('.todo-count');
  }

  getClearCompletedButton() {
    return this.document.querySelector('.clear-completed');
  }

  getFilterLinks() {
    return Array.from(this.document.querySelectorAll('.filters a'));
  }
}

setWorldConstructor(AppWorld);

